// Clean-room TSVC s235 profile; see package rights note.
#include <cstddef>
#include <cstdint>
static void put64(std::uint8_t*o,std::size_t p,std::int64_t v){auto b=static_cast<std::uint64_t>(v);for(std::size_t k=0;k<8;++k){o[p+k]=static_cast<std::uint8_t>(b);b>>=8;}}
extern "C" std::int64_t tsvc_s235_fused_vector_matrix_recurrence(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap){if(!in||len<15||len>153)return -1;auto nr=in[0];if(nr<2||nr>8)return -1;auto n=static_cast<std::size_t>(nr),nn=n*n;if(len!=1+3*n+2*nn)return -1;std::int64_t a[8],b[8],c[8],aa[64],bb[64];std::size_t p=1;for(std::size_t i=0;i<n;++i){auto x=in[p++];if(x< -1||x>1)return -1;a[i]=x;}for(std::size_t i=0;i<n;++i){auto x=in[p++];if(x< -1||x>1)return -1;b[i]=x;}for(std::size_t i=0;i<n;++i){auto x=in[p++];if(x< -1||x>1)return -1;c[i]=x;}for(std::size_t i=0;i<nn;++i){auto x=in[p++];if(x< -1||x>1)return -1;aa[i]=x;}for(std::size_t i=0;i<nn;++i){auto x=in[p++];if(x< -1||x>1)return -1;bb[i]=x;}if(!out||cap<8*(n+nn))return -2;for(std::size_t col=0;col<n;++col){a[col]+=b[col]*c[col];for(std::size_t row=1;row<n;++row){auto k=row*n+col;aa[k]=aa[k-n]+bb[k]*a[col];}}for(std::size_t i=0;i<n;++i)put64(out,8*i,a[i]);for(std::size_t i=0;i<nn;++i)put64(out,8*(n+i),aa[i]);return static_cast<std::int64_t>(n+nn);}
